mapper.select:
SELECT p.PREPAYMENT_ID as prepaymentId, p.PREPAYMENT_NO as prepaymentNo, p.SUPPLIER_ID as supplierId, s.SUPPLIER_NAME as supplierName, p.PREPAYMENT_AMOUNT as prepaymentAmount, p.OFFSET_AMOUNT as offsetAmount, p.REMAINING_AMOUNT as remainingAmount, p.PREPAYMENT_STATUS as prepaymentStatus, p.PREPAYMENT_DATE as prepaymentDate, p.PAYMENT_METHOD as paymentMethod, p.SUMMARY as summary, p.REMARKS as remarks, p.CREATE_TIME as createTime, p.CREATE_BY as createBy FROM TBL_PREPAYMENT p LEFT JOIN TBL_SUPPLIER s ON p.SUPPLIER_ID = s.SUPPLIER_ID AND s.IS_DELETED = 0 WHERE p.IS_DELETED = 0
AND p.PREPAYMENT_NO LIKE '%' || #{param.prepaymentNo} || '%'
AND p.SUPPLIER_ID = #{param.supplierId}
AND p.PREPAYMENT_STATUS = #{param.prepaymentStatus}
ORDER BY p.CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_PREPAYMENT p
WHERE p.IS_DELETED = 0

    AND p.PREPAYMENT_NO LIKE '%' || #{param.prepaymentNo} || '%'


    AND p.SUPPLIER_ID = #{param.supplierId}


    AND p.PREPAYMENT_STATUS = #{param.prepaymentStatus}
